class RateTree:
    def __init__(self, spec):
        self._cap = {}
        self._rate = {}
        self._parent = {}
        self._tokens = {}
        self._last = {}
        for name, (capacity, refill_rate, parent) in spec.items():
            self._cap[name] = capacity
            self._rate[name] = refill_rate
            self._parent[name] = parent
            self._tokens[name] = capacity  # every bucket starts full
            self._last[name] = None        # not yet touched

    def _chain(self, name):
        chain = []
        cur = name
        while cur is not None:
            chain.append(cur)
            cur = self._parent[cur]
        return chain

    def _available(self, name, now):
        last = self._last[name]
        if last is None:
            return self._tokens[name]
        elapsed = now - last
        if elapsed < 0:          # now earlier than last-seen -> no refill
            elapsed = 0.0
        refilled = self._tokens[name] + elapsed * self._rate[name]
        cap = self._cap[name]
        return cap if refilled > cap else refilled

    def _commit(self, name, now, new_tokens):
        self._tokens[name] = new_tokens
        last = self._last[name]
        if last is None or now > last:   # never move a node's clock backward
            self._last[name] = now

    def allow(self, name, n=1.0, now=0.0):
        chain = self._chain(name)
        avails = {}
        ok = True
        for node in chain:
            a = self._available(node, now)
            avails[node] = a
            if a < n:
                ok = False
        for node in chain:              # touch (refresh) every ancestor either way
            new_tokens = avails[node]
            if ok:
                new_tokens -= n         # debit only on success
            self._commit(node, now, new_tokens)
        return ok

