            self._tokens[name] = float(capacity)  # every bucket starts full
            self._last[name] = None

    def _chain(self, name):
        chain, node = [], name
        while node is not None:
            chain.append(node)
            node = self._parent[node]
        return chain

    def _touch(self, node, now):
        last = self._last[node]
        elapsed = 0.0 if last is None else now - last
        if elapsed < 0:  # now earlier than last-seen => no negative refill
            elapsed = 0.0
        self._tokens[node] = min(
            self._cap[node],
            self._tokens[node] + elapsed * self._rate[node],
        )
        if last is None or now > last:
            self._last[node] = now

    def allow(self, name, n=1.0, now=0.0):
        chain = self._chain(name)
        for node in chain:          # touching refills node + every ancestor
            self._touch(node, now)
        if all(self._tokens[node] >= n for node in chain):
            for node in chain:      # all-or-nothing debit
                self._tokens[node] -= n
            return True
        return False

