    for start, end, weight in events:
        deltas.append((start, weight))
        deltas.append((end, -weight))
    deltas.sort()
    peak = 0
    peak_t = 0
    load = 0
    i = 0
    n = len(deltas)
    while i < n:
        t = deltas[i][0]
        # apply all deltas at this same time before evaluating the load
        while i < n and deltas[i][0] == t:
            load += deltas[i][1]
            i += 1
        if load > peak:
            peak = load
            peak_t = t
    return (peak, peak_t)

def elapsed_seconds(tz_name, start, end):
    from datetime import datetime
    from zoneinfo import ZoneInfo

    zone = ZoneInfo(tz_name)
    fmt = "%Y-%m-%d %H:%M:%S"

    def to_epoch(reading):
        naive = datetime.strptime(reading, fmt)
        aware = naive.replace(tzinfo=zone, fold=0)
        return aware.timestamp()

    return to_epoch(end) - to_epoch(start)

