def find_all_occurrences(text, pattern):
    n, m = len(text), len(pattern)
    if m > n:
        return []

    # Build KMP longest-proper-prefix-suffix (failure) table for the pattern.
    lps = [0] * m
    length = 0
    i = 1
    while i < m:
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        elif length > 0:
            length = lps[length - 1]
        else:
            lps[i] = 0
            i += 1

    # Scan text once; on a full match, use the failure table to keep going
    # (this is what allows overlapping matches without rescanning).
    result = []
    i = 0  # index into text
    j = 0  # index into pattern
    while i < n:
        if text[i] == pattern[j]:
            i += 1
            j += 1
            if j == m:
                result.append(i - m)
                j = lps[j - 1]
        elif j > 0:
            j = lps[j - 1]
        else:
            i += 1

    return result

